import json
from dataclasses import dataclass, field
from datetime import date

@dataclass
class Todo:
    id: int
    title: str
    done: bool = False
    created_at: str = field(default_factory=lambda: str(date.today()))

class TodoList:
    def __init__(self):
        self.todos = []
        self._next_id = 1

    def add(self, title):
        todo = Todo(self._next_id, title)
        self.todos.append(todo)
        self._next_id += 1
        return todo

    def find(self, todo_id):
        for t in self.todos:
            if t.id == todo_id:
                return t
        return None

    def complete(self, todo_id):
        todo = self.find(todo_id)
        if todo:
            todo.done = True
        return todo is not None

    def delete(self, todo_id):
        before = len(self.todos)
        self.todos = [t for t in self.todos if t.id != todo_id]
        return len(self.todos) < before

    def pending_count(self):
        return sum(1 for t in self.todos if not t.done)

    def list_all(self):
        if not self.todos:
            print('  (nothing here yet)')
        for t in self.todos:
            mark = 'x' if t.done else ' '
            print(f'  [{mark}] {t.id}. {t.title}  ({t.created_at})')

