GREEN = '\033[92m'
DIM = '\033[2m'
RESET = '\033[0m'

def show_list(todos):
    if not todos.todos:
        print('  (nothing here yet)')
    for t in todos.todos:
        if t.done:
            print(f'  {GREEN}[x] {t.id}. {t.title}{RESET}  {DIM}{t.created_at}{RESET}')
